//! TLS for the control channel.
//!
//! Mumble servers almost always run on a self-signed certificate ("Murmur Autogenerated
//! Certificate"), so the usual web PKI check would reject nearly all of them. Mumble's own
//! model is trust on first use: remember the certificate's fingerprint the first time, and
//! refuse to connect if it ever changes. That is what this verifier does. The handshake
//! signature is still checked, so the server must hold the key for the certificate it shows.

use std::sync::{Arc, Mutex};

use rustls::client::danger::{HandshakeSignatureValid, ServerCertVerified, ServerCertVerifier};
use rustls::crypto::{verify_tls12_signature, verify_tls13_signature, CryptoProvider};
use rustls::pki_types::{CertificateDer, ServerName, UnixTime};
use rustls::{CertificateError, ClientConfig, DigitallySignedStruct, SignatureScheme};
use sha2::{Digest, Sha256};

/// SHA-256 of the DER certificate as lowercase hex.
pub fn fingerprint(der: &[u8]) -> String {
    Sha256::digest(der)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

/// Compare fingerprints the way people paste them: case and `:` or space separators ignored.
pub fn fingerprints_match(a: &str, b: &str) -> bool {
    let clean = |value: &str| -> String {
        value
            .chars()
            .filter(|c| c.is_ascii_hexdigit())
            .map(|c| c.to_ascii_lowercase())
            .collect()
    };
    let (a, b) = (clean(a), clean(b));
    !a.is_empty() && a == b
}

/// Where the verifier leaves the fingerprint it saw, so the caller can pin or report it.
pub type SeenFingerprint = Arc<Mutex<Option<String>>>;

#[derive(Debug)]
struct PinningVerifier {
    provider: Arc<CryptoProvider>,
    pinned: Option<String>,
    seen: SeenFingerprint,
}

impl ServerCertVerifier for PinningVerifier {
    fn verify_server_cert(
        &self,
        end_entity: &CertificateDer<'_>,
        _intermediates: &[CertificateDer<'_>],
        _server_name: &ServerName<'_>,
        _ocsp_response: &[u8],
        _now: UnixTime,
    ) -> Result<ServerCertVerified, rustls::Error> {
        let actual = fingerprint(end_entity.as_ref());
        *self
            .seen
            .lock()
            .unwrap_or_else(|poison| poison.into_inner()) = Some(actual.clone());
        match &self.pinned {
            Some(expected) if !fingerprints_match(expected, &actual) => Err(
                rustls::Error::InvalidCertificate(CertificateError::ApplicationVerificationFailure),
            ),
            _ => Ok(ServerCertVerified::assertion()),
        }
    }

    fn verify_tls12_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> Result<HandshakeSignatureValid, rustls::Error> {
        verify_tls12_signature(
            message,
            cert,
            dss,
            &self.provider.signature_verification_algorithms,
        )
    }

    fn verify_tls13_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> Result<HandshakeSignatureValid, rustls::Error> {
        verify_tls13_signature(
            message,
            cert,
            dss,
            &self.provider.signature_verification_algorithms,
        )
    }

    fn supported_verify_schemes(&self) -> Vec<SignatureScheme> {
        self.provider
            .signature_verification_algorithms
            .supported_schemes()
    }
}

/// A client config that accepts the pinned certificate, or any certificate when nothing is
/// pinned yet. No client certificate is presented, so we connect as an unregistered user.
pub fn client_config(
    pinned: Option<String>,
) -> Result<(ClientConfig, SeenFingerprint), rustls::Error> {
    // Named explicitly: the app also links aws-lc-rs through other crates, and rustls
    // refuses to guess a process-wide default when two providers are present.
    let provider = Arc::new(rustls::crypto::ring::default_provider());
    let seen: SeenFingerprint = Arc::new(Mutex::new(None));
    let verifier = PinningVerifier {
        provider: provider.clone(),
        pinned,
        seen: seen.clone(),
    };
    let config = ClientConfig::builder_with_provider(provider)
        .with_safe_default_protocol_versions()?
        .dangerous()
        .with_custom_certificate_verifier(Arc::new(verifier))
        .with_no_client_auth();
    Ok((config, seen))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fingerprint_is_lowercase_hex_sha256() {
        // SHA-256 of the empty input.
        assert_eq!(
            fingerprint(b""),
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
        );
    }

    #[test]
    fn fingerprints_compare_loosely_but_never_match_empty() {
        assert!(fingerprints_match("AB:cd:01", "abcd01"));
        assert!(fingerprints_match("ab cd 01", "ABCD01"));
        assert!(!fingerprints_match("abcd01", "abcd02"));
        assert!(!fingerprints_match("", ""));
        assert!(!fingerprints_match("::", "  "));
    }
}
